<?php
declare(strict_types=1);
require_once __DIR__.'/operations.php';
require_once __DIR__.'/equipment-catalog.php';
require_once __DIR__.'/commercial.php';
function qhse_can_view(array $user):bool{return (bool)($user['is_active']??false)&&email_access_allowed($user);}
function qhse_can_manage(array $user):bool{return qhse_can_view($user)&&in_array($user['role'],['OWNER_ADMIN','ADMIN','OPS_MANAGER','SUPERVISOR'],true);}
function qhse_roles(array $user):array{$assigned=array_column(rows('SELECT qhse_role FROM qhse_user_roles WHERE owner_id=? AND user_id=? ORDER BY qhse_role',[$user['owner_id'],$user['id']]),'qhse_role');return $assigned?:[$user['role']==='OWNER_ADMIN'?'QHSE_ADMINISTRATOR':'QHSE_VIEWER'];}
function qhse_count(string $sql,array $params):int{return (int)(rows($sql,$params)[0]['n']??0);}
function qhse_overview(array $user):array
{
 if(!qhse_can_view($user))throw new DomainException('Your account cannot access QHSE.',403);
 $owner=$user['owner_id'];$scope='e.owner_id=?';$params=[$owner];
 if($user['role']!=='OWNER_ADMIN'){$scope.=' AND EXISTS(SELECT 1 FROM user_scopes us WHERE us.user_id=? AND us.site_id=ev.site_id AND us.unit_id=ev.unit_id)';$params[]=$user['id'];}
 if($user['role']==='OPERATOR'){$scope.=' AND EXISTS(SELECT 1 FROM equipment_operator_assignments ea WHERE ea.equipment_id=e.id AND ea.operator_user_id=? AND ea.unassigned_at IS NULL)';$params[]=$user['id'];}
 $maintenance=' FROM maintenance_records m JOIN equipment e ON e.id=m.equipment_id JOIN equipment_status_view ev ON ev.id=e.id WHERE '.$scope;
 $alerts=' FROM alerts a JOIN equipment e ON e.id=a.equipment_id JOIN equipment_status_view ev ON ev.id=e.id WHERE '.$scope;
 $calibrationTotal=qhse_count("SELECT COUNT(*) n FROM qhse_certificates WHERE owner_id=? AND certificate_type IN ('PRESSURE_GAUGE_CALIBRATION','PRESSURE_RELIEF_VALVE_CALIBRATION') AND status='ISSUED'",[$owner]);
 $calibrationValid=qhse_count("SELECT COUNT(*) n FROM qhse_certificates WHERE owner_id=? AND certificate_type IN ('PRESSURE_GAUGE_CALIBRATION','PRESSURE_RELIEF_VALVE_CALIBRATION') AND status='ISSUED' AND (expiry_date IS NULL OR expiry_date>=UTC_DATE())",[$owner]);
 $metrics=['open_ncrs'=>0,'capas_due'=>0,
  'certificates_expiring'=>qhse_count("SELECT COUNT(*) n FROM qhse_certificates WHERE owner_id=? AND status='ISSUED' AND expiry_date BETWEEN UTC_DATE() AND DATE_ADD(UTC_DATE(),INTERVAL 30 DAY)",[$owner]),
  'calibration_due'=>qhse_count("SELECT COUNT(*) n FROM qhse_certificates WHERE owner_id=? AND status='ISSUED' AND certificate_type IN ('PRESSURE_GAUGE_CALIBRATION','PRESSURE_RELIEF_VALVE_CALIBRATION') AND expiry_date<=DATE_ADD(UTC_DATE(),INTERVAL 30 DAY)",[$owner]),
  'open_incidents'=>qhse_count('SELECT COUNT(*) n'.$alerts." AND a.kind='SAFETY' AND a.status IN ('OPEN','ACKNOWLEDGED','ESCALATED')",$params),
  'open_audit_findings'=>0,'high_risks'=>qhse_count('SELECT COUNT(*) n'.$alerts." AND a.severity IN ('CRITICAL','HIGH') AND a.status IN ('OPEN','ACKNOWLEDGED','ESCALATED')",$params),
  'pending_approvals'=>qhse_count("SELECT COUNT(*) n FROM qhse_controls WHERE owner_id=? AND status='DRAFT'",[$owner]),
  'incomplete_records'=>qhse_count("SELECT COUNT(*) n FROM qhse_completion_alerts WHERE owner_id=? AND status='OPEN'",[$owner]),
  'inspections_due'=>0,'certificates_issued'=>qhse_count("SELECT COUNT(*) n FROM qhse_certificates WHERE owner_id=? AND status='ISSUED'",[$owner]),'calibration_compliance'=>$calibrationTotal?round($calibrationValid*100/$calibrationTotal):null,'open_customer_quality_issues'=>0,
  'hse_events'=>qhse_count('SELECT COUNT(*) n'.$alerts." AND a.kind='SAFETY' AND a.triggered_at>=DATE_FORMAT(UTC_TIMESTAMP(),'%Y-%m-01')",$params),
  'environmental_events'=>qhse_count("SELECT COUNT(*) n FROM qhse_activity_events WHERE owner_id=? AND domain='ENVIRONMENT' AND occurred_at>=DATE_FORMAT(UTC_TIMESTAMP(),'%Y-%m-01')",[$owner]),
  'maintenance_due'=>qhse_count('SELECT COUNT(*) n'.$maintenance." AND m.status IN ('SCHEDULED','IN_PROGRESS') AND m.due_at<=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 DAY)",$params)];
 $attention=[];$rules=[['certificates_expiring','Certificates expiring','Certificates expire within 30 days.','high','Certificates'],['calibration_due','Calibration due','Reference instruments require calibration.','high','Calibration'],['capas_due','CAPAs due','Corrective actions are due or overdue.','critical','NCR & CAPA'],['high_risks','High risks','High or critical operational risks remain open.','critical','Risk & MOC'],['pending_approvals','Pending approvals','QHSE records await authorized approval.','medium','Approvals'],['incomplete_records','Records need completion','Quick-created records still need their full operational profiles.','medium','Data quality'],['maintenance_due','Maintenance evidence due','Maintenance work falls due within 30 days.','medium','Maintenance']];
 foreach($rules as [$key,$title,$copy,$severity,$area])if(($metrics[$key]??0)>0)$attention[]=['count'=>$metrics[$key],'title'=>$title,'copy'=>$copy,'severity'=>$severity,'area'=>$area];
 usort($attention,fn($a,$b)=>array_search($a['severity'],['critical','high','medium'],true)<=>array_search($b['severity'],['critical','high','medium'],true));
 $activity=rows('SELECT a.*,u.full_name actor_name FROM qhse_activity_events a LEFT JOIN users u ON u.id=a.actor_id AND u.owner_id=a.owner_id WHERE a.owner_id=? ORDER BY a.occurred_at DESC,a.id DESC LIMIT 20',[$owner]);
 if(!$activity)$activity=rows("SELECT CONCAT('audit-',a.id) id,'GOVERNANCE' domain,REPLACE(a.action,'.',' ') title,NULL summary,'INFO' severity,a.entity_type source_type,a.entity_id source_id,CASE a.entity_type WHEN 'equipment' THEN CONCAT('equipment?id=',a.entity_id) WHEN 'maintenance' THEN CONCAT('maintenance?id=',a.entity_id) WHEN 'alert' THEN CONCAT('alert?id=',a.entity_id) END source_url,a.created_at occurred_at,u.full_name actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id AND u.owner_id=a.owner_id WHERE a.owner_id=? AND a.entity_type IN ('equipment','maintenance','alert') ORDER BY a.id DESC LIMIT 12",[$owner]);
 $standards=rows('SELECT s.*,COUNT(DISTINCT c.id) control_count,COUNT(DISTINCT el.id) evidence_count FROM qhse_standards s LEFT JOIN qhse_control_standards cs ON cs.standard_id=s.id LEFT JOIN qhse_controls c ON c.id=cs.control_id AND c.owner_id=? LEFT JOIN qhse_evidence_links el ON el.control_id=c.id AND el.owner_id=? GROUP BY s.id ORDER BY s.code',[$owner,$owner]);
 return compact('metrics','attention','activity','standards')+['roles'=>qhse_roles($user)];
}
function qhse_assistant_answer(array $state,string $prompt):array
{
 $m=$state['metrics'];$attention=$state['attention'];
 if($prompt==='attention')return ['title'=>'What requires attention?','answer'=>$attention?implode(' ',array_map(fn($i)=>$i['count'].' '.$i['copy'],$attention)):'No deterministic due-date or high-risk rule currently requires attention.'];
 if($prompt==='quality')return ['title'=>'Recurring quality problems','answer'=>'No recurring quality pattern can be established yet. This view will use linked NCR and customer-quality records as those registers are introduced.'];
 if($prompt==='activity')return ['title'=>'QHSE activity this month','answer'=>count($state['activity']).' recent linked activities are visible. '.$m['hse_events'].' HSE and '.$m['environmental_events'].' environmental events were recorded this month.'];
 if($prompt==='kpi')return ['title'=>'KPI explanation','answer'=>'High risks come from open high or critical operational alerts; due items come from record dates. No model changes these totals. Open a source record to investigate movement.'];
 return ['title'=>'Current QHSE position','answer'=>'There are '.$m['high_risks'].' high risks, '.$m['open_incidents'].' open incidents, '.$m['maintenance_due'].' maintenance items due within 30 days, and '.$m['pending_approvals'].' pending approvals. '.($attention?'Review the Attention Center for prioritized source records.':'No deterministic attention rule is currently triggered.')];
}

function qhse_text(array $input,string $key,int $max=5000,bool $required=false):string{$value=trim((string)($input[$key]??''));if($required&&$value==='')throw new DomainException(ucwords(str_replace('_',' ',$key)).' is required.',422);if(mb_strlen($value)>$max)throw new DomainException(ucwords(str_replace('_',' ',$key)).' is too long.',422);return $value;}
function qhse_certificate_type_label(string $type):string{return ucwords(strtolower(str_replace('_',' ',$type)));}
function qhse_technical_value(mixed $value):string{if(is_array($value)){if(array_key_exists('value',$value))return trim((string)$value['value'].' '.(string)($value['unit']??''));return implode('; ',array_map(fn($item)=>is_array($item)?implode(' / ',array_map('strval',$item)):(string)$item,$value));}return (string)$value;}
function qhse_status_badge(string $status):string{$label=ucwords(strtolower(str_replace('_',' ',$status)));$tone=in_array($status,['VALID','ISSUED','APPROVED'],true)?'success':(in_array($status,['EXPIRED','REVOKED','REJECTED','FAIL'],true)?'danger':(in_array($status,['EXPIRING_SOON','AWAITING_REVIEW','CONDITIONAL'],true)?'warning':'neutral'));return '<span class="qhse-badge '.$tone.'">'.e($label).'</span>';}
function qhse_certificate_schema(string $type):array
{
 $pressureUnits=['psi','bar','kPa','MPa'];$sizeUnits=['IN','MM','CM','M'];$timeUnits=['seconds','minutes','hours'];$yesNo=['YES','NO'];$passFail=['PASS','FAIL'];$overall=['PASS','FAIL','CONDITIONAL'];
 $field=fn(string $key,string $label,string $kind='text',bool $required=false,array $options=[])=>compact('key','label','kind','required','options');
 return match($type){
  'HYDROSTATIC_PRESSURE_TEST'=>['multiple_equipment'=>true,'reference_count'=>1,'multiple_reference_equipment'=>true,'sections'=>[
   ['title'=>'Test conditions','fields'=>[$field('test_medium','Test medium','text',true),$field('proof_pressure','Proof test pressure','measure',true,$pressureUnits),$field('ram_pressure','Ram pressure','measure',false,$pressureUnits),$field('final_hold_time','Final hold time','measure',true,$timeUnits)]],
   ['title'=>'Result','fields'=>[$field('overall_result','Overall result','select',true,$passFail),$field('result_statement','Result narrative','textarea',true)]],
  ]],
  'PRESSURE_PUMP_TEST'=>['multiple_equipment'=>false,'reference_count'=>1,'sections'=>[
   ['title'=>'Pump and test conditions','fields'=>[$field('working_pressure_rating','Working pressure rating','measure',true,$pressureUnits),$field('connection_configuration','Connection / configuration'),$field('test_medium','Test medium','text',true),$field('test_pressure','Test pressure','measure',true,$pressureUnits),$field('working_pressure','Working pressure','measure',true,$pressureUnits),$field('hold_time','Hold time','measure',true,$timeUnits),$field('test_cycles','Number of test cycles','number',true)]],
   ['title'=>'Test-cycle results','kind'=>'pump_matrix'],
   ['title'=>'Final result','fields'=>[$field('overall_result','Overall result','select',true,$overall),$field('equipment_condition','Equipment condition','textarea'),$field('observations','Observations','textarea'),$field('corrective_work','Corrective work performed','textarea'),$field('remarks','Remarks','textarea')]],
  ]],
  'PRESSURE_GAUGE_CALIBRATION'=>['multiple_equipment'=>false,'reference_count'=>2,'sections'=>[
   ['title'=>'Instrument under calibration','fields'=>[$field('accuracy','Accuracy','text',true),$field('range_min','Range minimum','number',true),$field('range_max','Range maximum','number',true),$field('pressure_unit','Pressure unit','select',true,$pressureUnits),$field('gauge_size','Gauge size'),$field('connection','Connection'),$field('calibration_method','Calibration method','text',true),$field('acceptance_tolerance','Acceptance tolerance','number',true)]],
   ['title'=>'Calibration readings','kind'=>'calibration_matrix'],
   ['title'=>'Calibration result','fields'=>[$field('overall_result','Overall result','select',true,$passFail),$field('remarks','Remarks','textarea'),$field('as_found_condition','As-found condition','textarea'),$field('adjustment_required','Adjustment required','select',false,$yesNo),$field('adjustment_performed','Adjustment performed','select',false,$yesNo),$field('as_left_condition','As-left condition','textarea')]],
  ]],
  'PRESSURE_RELIEF_VALVE_CALIBRATION'=>['multiple_equipment'=>false,'reference_count'=>1,'sections'=>[
   ['title'=>'PRV details','fields'=>[$field('size','Equipment size','measure',false,$sizeUnits),$field('connection','Connection'),$field('previous_set_pressure','Previous set pressure','measure',true,$pressureUnits),$field('required_set_pressure','Required / new set pressure','measure',true,$pressureUnits),$field('back_pressure','Back pressure or Nil','measure',false,$pressureUnits)]],
   ['title'=>'Pre-pop report','fields'=>[$field('prepop_performed','Pre-pop performed','select',true,$yesNo),$field('test_medium','Test medium','text',true),$field('prepop_pressure','Pre-pop pressure','measure',false,$pressureUnits),$field('reason_not_prepop','Reason not pre-popped','conditional_text',false,['depends'=>'prepop_performed','value'=>'NO']),$field('prepop_result','Pre-pop result','select',false,$passFail)]],
   ['title'=>'Leakage test','fields'=>[$field('leakage_test_performed','Leakage test performed','select',true,$yesNo),$field('leakage_test_pressure','Test pressure','measure',false,$pressureUnits),$field('test_pressure_percentage','Test pressure as % of set pressure','calculated'),$field('leakage_hold_time','Hold time','measure',false,$timeUnits),$field('leakage_detected','Leakage detected','select',false,$yesNo),$field('pressure_drop','Pressure drop','measure',false,$pressureUnits),$field('leakage_test_result','Leakage test result','select',false,$passFail)]],
   ['title'=>'Final test result','fields'=>[$field('final_set_pressure','Final set pressure','measure',true,$pressureUnits),$field('leakage_result','Leakage result','select',true,$passFail),$field('calibration_result','Calibration result','select',true,$passFail),$field('overall_result','Overall result','select',true,$overall),$field('comments','Comments','textarea')]],
  ]],default=>throw new DomainException('Unsupported certificate template.',422)};
}
function qhse_technical_payload(array $input,string $type):array
{
 $data=json_decode((string)($input['technical_json']??'{}'),true);if(!is_array($data))throw new DomainException('Technical results are invalid.',422);$schema=qhse_certificate_schema($type);
 foreach($schema['sections'] as $section)foreach($section['fields']??[] as $field){$value=$data[$field['key']]??'';$empty=is_array($value)?trim((string)($value['value']??''))==='':trim((string)$value)==='';if($field['required']&&$empty)throw new DomainException($field['label'].' is required.',422);}
 if($type==='PRESSURE_GAUGE_CALIBRATION'){$tolerance=(float)($data['acceptance_tolerance']??0);$points=[];foreach((array)($data['calibration_points']??[]) as $point){$reference=(float)($point['reference']??0);$instrument=(float)($point['instrument']??0);$error=round($instrument-$reference,6);$points[]=['point'=>mb_substr((string)($point['point']??''),0,30),'reference'=>$reference,'instrument'=>$instrument,'error'=>$error,'result'=>abs($error)<=$tolerance?'PASS':'FAIL'];}$data['calibration_points']=$points;}
 if($type==='PRESSURE_PUMP_TEST'){$cycles=[];foreach((array)($data['pump_cycles']??[]) as $cycle)$cycles[]=['input_pressure'=>mb_substr((string)($cycle['input_pressure']??''),0,60),'output'=>mb_substr((string)($cycle['output']??''),0,60),'leakage'=>in_array(($cycle['leakage']??''),['OK','NOT_OK'],true)?$cycle['leakage']:'','valves'=>in_array(($cycle['valves']??''),['OK','NOT_OK'],true)?$cycle['valves']:''];$data['pump_cycles']=$cycles;}
 if($type==='PRESSURE_RELIEF_VALVE_CALIBRATION'){$test=(float)($data['leakage_test_pressure']['value']??0);$set=(float)($data['required_set_pressure']['value']??0);$data['test_pressure_percentage']=$set>0?round($test/$set*100,2):null;}
 return $data;
}
function qhse_certificate_display_status(array $certificate):string
{
 if($certificate['status']!=='ISSUED')return $certificate['status'];$today=gmdate('Y-m-d');
 if(!empty($certificate['expiry_date'])&&$certificate['expiry_date']<$today)return 'EXPIRED';
 if(!empty($certificate['expiry_date'])&&$certificate['expiry_date']<=gmdate('Y-m-d',time()+2592000))return 'EXPIRING_SOON';
 return 'VALID';
}
function qhse_can_approve(array $user):bool{return in_array($user['role'],['OWNER_ADMIN','ADMIN'],true)||array_intersect(qhse_roles($user),['APPROVER','QUALITY_MANAGER','QHSE_ADMINISTRATOR']);}
function qhse_certificate_number(array $user):string
{
 db()->prepare("INSERT IGNORE INTO qhse_certificate_sequences(owner_id,prefix,next_number) VALUES(?,'CERT',1)")->execute([$user['owner_id']]);
 $row=rows('SELECT prefix,next_number FROM qhse_certificate_sequences WHERE owner_id=? FOR UPDATE',[$user['owner_id']])[0];
 db()->prepare('UPDATE qhse_certificate_sequences SET next_number=next_number+1 WHERE owner_id=?')->execute([$user['owner_id']]);
 return $row['prefix'].'-'.gmdate('Y').'-'.str_pad((string)$row['next_number'],5,'0',STR_PAD_LEFT);
}
function qhse_certificate(array $user,string $id,bool $lock=false):array
{
 $row=rows("SELECT c.*,t.name template_name,t.field_schema,t.presentation_schema,t.legal_statement,cu.name customer_name,cu.billing_address customer_address,b.brand_name,tech.full_name technician_name,ins.full_name inspector_name,rev.full_name reviewer_name,app.full_name approver_name FROM qhse_certificates c JOIN qhse_certificate_templates t ON t.id=c.template_id JOIN commercial_customers cu ON cu.id=c.customer_id LEFT JOIN commercial_brands b ON b.id=c.brand_id LEFT JOIN users tech ON tech.id=c.technician_id LEFT JOIN users ins ON ins.id=c.inspector_id LEFT JOIN users rev ON rev.id=c.reviewer_id LEFT JOIN users app ON app.id=c.approver_id WHERE c.id=? AND c.owner_id=?".($lock?' FOR UPDATE':''),[$id,$user['owner_id']])[0]??null;
 if(!$row)throw new DomainException('Certificate not found.',404);$row['customer_site']=null;$row['display_status']=qhse_certificate_display_status($row);
 $row['equipment']=rows('SELECT ce.*,e.name,e.asset_code,e.serial_no,t.name type_name,b.name brand_name,m.name model_name FROM qhse_certificate_equipment ce JOIN equipment e ON e.id=ce.equipment_id LEFT JOIN equipment_types t ON t.id=e.type_id LEFT JOIN equipment_brands b ON b.id=e.brand_id LEFT JOIN equipment_models m ON m.id=e.model_id WHERE ce.certificate_id=? ORDER BY ce.sort_order,e.name',[$id]);
 $row['references']=rows('SELECT r.*,e.name,e.asset_code,e.serial_no FROM qhse_certificate_reference_equipment r JOIN equipment e ON e.id=r.equipment_id WHERE r.certificate_id=? ORDER BY e.name',[$id]);
 $row['pressure_items']=rows('SELECT * FROM qhse_pressure_test_items WHERE certificate_id=? ORDER BY sort_order,id',[$id]);
 $row['signatories']=rows('SELECT s.*,a.signatory_name library_name,a.role_title,a.signature_mime,a.signature_data,a.stamp_mime,a.stamp_data FROM qhse_certificate_signatories s LEFT JOIN qhse_signature_assets a ON a.id=s.signature_asset_id WHERE s.certificate_id=? ORDER BY FIELD(s.signatory_role,"TECHNICIAN","QA_REVIEWER","APPROVER","CLIENT_REPRESENTATIVE")',[$id]);
 $row['events']=rows('SELECT ev.*,u.full_name actor_name FROM qhse_certificate_events ev JOIN users u ON u.id=ev.actor_id WHERE ev.certificate_id=? ORDER BY ev.id DESC',[$id]);return $row;
}
function qhse_equipment_snapshot(array $row):array{return ['id'=>$row['equipment_id']??$row['id'],'aid'=>$row['asset_code'],'description'=>$row['name'],'equipment_type'=>$row['type_name']??null,'manufacturer'=>$row['brand_name']??null,'model'=>$row['model_name']??null,'serial_number'=>$row['serial_no']??null];}
function qhse_certificate_event(array $user,string $id,string $event,?string $from,?string $to,string $notes=''):void
{
 db()->prepare('INSERT INTO qhse_certificate_events(certificate_id,actor_id,event_type,from_status,to_status,notes) VALUES(?,?,?,?,?,?)')->execute([$id,$user['id'],$event,$from,$to,$notes?:null]);
 db()->prepare("INSERT INTO qhse_activity_events(id,owner_id,actor_id,event_type,domain,title,summary,severity,source_module,source_type,source_id,source_url) VALUES(?,?,?,?,'QUALITY',?,?,?,'qhse','certificate',?,?)")->execute([uuid(),$user['owner_id'],$user['id'],$event,ucwords(strtolower(str_replace('_',' ',$event))),$notes?:null,in_array($event,['CERTIFICATE_REJECTED','CERTIFICATE_REVOKED'],true)?'HIGH':'INFO',$id,'qhse-certificates?id='.urlencode($id)]);
 operation_audit($user,'qhse.'.strtolower($event),'qhse_certificate',$id,null,['from'=>$from,'to'=>$to]);
}
function qhse_certificate_save(array $user,array $input):string
{
 if(!qhse_can_manage($user))throw new DomainException('Your role cannot create certificates.',403);
 $id=qhse_text($input,'id',36);$existing=$id?qhse_certificate($user,$id,true):null;if($existing&&!in_array($existing['status'],['DRAFT','REJECTED'],true))throw new DomainException('Only draft or rejected certificates can be edited.',409);
 $templateId=qhse_text($input,'template_id',36,true);$template=rows('SELECT * FROM qhse_certificate_templates WHERE id=? AND is_active=1 AND (owner_id IS NULL OR owner_id=?) ORDER BY owner_id DESC LIMIT 1',[$templateId,$user['owner_id']])[0]??null;if(!$template)throw new DomainException('Choose an active certificate template.',422);
 $customer=rows('SELECT id FROM commercial_customers WHERE id=? AND organization_id=?',[qhse_text($input,'customer_id',36,true),$user['owner_id']])[0]??null;if(!$customer)throw new DomainException('Choose a customer from your customer directory.',422);
 $equipment=array_values(array_unique(array_filter(array_map('strval',(array)($input['equipment_ids']??[])))));$manualItems=[];foreach((array)($input['manual_items']??[]) as $item){if(!is_array($item))continue;$name=mb_substr(trim((string)($item['name']??'')),0,255);if($name==='')continue;$manualItems[]=['name'=>$name,'asset_code'=>mb_substr(trim((string)($item['asset_code']??'')),0,100),'range_text'=>mb_substr(trim((string)($item['range_text']??'')),0,150),'test_pressure'=>mb_substr(trim((string)($item['test_pressure']??'')),0,100)];}
 $submittedAssemblies=[];foreach((array)($input['subassemblies']??[]) as $assemblyId=>$item){if(!is_array($item)||empty($item['included']))continue;$submittedAssemblies[(string)$assemblyId]=['equipment_id'=>(string)($item['equipment_id']??''),'serial_number'=>mb_substr(trim((string)($item['serial_number']??'')),0,100),'range_text'=>mb_substr(trim((string)($item['range_text']??'')),0,150),'test_pressure'=>mb_substr(trim((string)($item['test_pressure']??'')),0,100)];foreach(['serial_number'=>'serial number','range_text'=>'range','test_pressure'=>'test pressure'] as $field=>$label)if($submittedAssemblies[(string)$assemblyId][$field]==='')throw new DomainException('Enter the '.$label.' for every included subassembly.',422);}
 $newAssemblies=[];foreach((array)($input['new_subassemblies']??[]) as $item){if(!is_array($item))continue;$name=mb_substr(trim((string)($item['name']??'')),0,255);if($name==='')continue;$entry=['equipment_id'=>(string)($item['equipment_id']??''),'name'=>$name,'serial_number'=>mb_substr(trim((string)($item['serial_number']??'')),0,100),'range_text'=>mb_substr(trim((string)($item['range_text']??'')),0,150),'test_pressure'=>mb_substr(trim((string)($item['test_pressure']??'')),0,100)];foreach(['serial_number'=>'serial number','range_text'=>'range','test_pressure'=>'test pressure'] as $field=>$label)if($entry[$field]==='')throw new DomainException('Enter the '.$label.' for every new subassembly.',422);$newAssemblies[]=$entry;}
 $isPressure=$template['certificate_type']==='HYDROSTATIC_PRESSURE_TEST';if(!$equipment&&!($isPressure&&$manualItems))throw new DomainException('Add at least one registered or manual tested item.',422);
 $assets=[];if($equipment){$marks=implode(',',array_fill(0,count($equipment),'?'));$assets=rows("SELECT e.*,t.name type_name,b.name brand_name,m.name model_name FROM equipment e LEFT JOIN equipment_types t ON t.id=e.type_id LEFT JOIN equipment_brands b ON b.id=e.brand_id LEFT JOIN equipment_models m ON m.id=e.model_id WHERE e.owner_id=? AND e.id IN ($marks)",[$user['owner_id'],...$equipment]);if(count($assets)!==count($equipment))throw new DomainException('One or more equipment records are outside your organization.',403);}
 foreach($newAssemblies as $assembly)if(!in_array($assembly['equipment_id'],$equipment,true))throw new DomainException('A new subassembly must belong to selected equipment.',422);
