function qhse_certificate_transition(array $user,string $id,string $action,string $notes=''):void
{
 $certificate=qhse_certificate($user,$id,true);$from=$certificate['status'];$map=['publish'=>[['DRAFT','AWAITING_REVIEW','APPROVED'],'ISSUED','CERTIFICATE_PUBLISHED'],'revoke'=>[['ISSUED'],'REVOKED','CERTIFICATE_REVOKED']];if(!isset($map[$action]))throw new DomainException('Invalid certificate action.',422);[$allowed,$to,$event]=$map[$action];if(!in_array($from,$allowed,true))throw new DomainException('This certificate cannot be '.str_replace('_',' ',strtolower($to)).' from its current status.',409);if($action==='publish'&&!qhse_can_manage($user))throw new DomainException('Your role cannot publish certificates.',403);if($action==='revoke'&&!qhse_can_approve($user))throw new DomainException('Your role cannot revoke certificates.',403);if($action==='revoke'&&trim($notes)==='')throw new DomainException('Add a reason for this action.',422);
