 $pdo=db();$pdo->beginTransaction();try{$sets='status=?';$params=[$to];if($action==='revoke'){$sets.=',revoked_at=UTC_TIMESTAMP(),rejection_reason=?';$params[]=$notes;}if($action==='publish'){
   $unit=['DAY'=>'day','WEEK'=>'week','MONTH'=>'month','YEAR'=>'year'][$certificate['validity_unit']]??null;if(!$unit||!(int)$certificate['validity_duration'])throw new DomainException('Set the certificate validity period before publishing.',409);$issuedOn=gmdate('Y-m-d');$testOn=$certificate['test_date']?:$issuedOn;$expires=(new DateTimeImmutable($testOn,new DateTimeZone('UTC')))->modify('+'.(int)$certificate['validity_duration'].' '.$unit)->format('Y-m-d');$certificate['issue_date']=$issuedOn;$certificate['valid_from']=$issuedOn;$certificate['expiry_date']=$expires;$snapshot=qhse_certificate_snapshot($user,$certificate);$sets.=',issue_date=?,valid_from=?,expiry_date=?,issued_at=UTC_TIMESTAMP(),issued_snapshot=?';array_push($params,$issuedOn,$issuedOn,$expires,json_encode($snapshot,JSON_THROW_ON_ERROR));
   foreach($certificate['equipment'] as $asset)db()->prepare('UPDATE qhse_certificate_equipment SET equipment_snapshot=? WHERE certificate_id=? AND equipment_id=?')->execute([json_encode(qhse_equipment_snapshot($asset),JSON_THROW_ON_ERROR),$id,$asset['equipment_id']]);
   foreach($certificate['references'] as $asset)db()->prepare('UPDATE qhse_certificate_reference_equipment SET equipment_snapshot=? WHERE certificate_id=? AND equipment_id=?')->execute([json_encode(['id'=>$asset['equipment_id'],'aid'=>$asset['asset_code'],'description'=>$asset['name'],'serial_number'=>$asset['serial_no']],JSON_THROW_ON_ERROR),$id,$asset['equipment_id']]);
  }$params[]=$id;$params[]=$user['owner_id'];db()->prepare("UPDATE qhse_certificates SET $sets WHERE id=? AND owner_id=?")->execute($params);qhse_certificate_event($user,$id,$event,$from,$to,$notes);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function qhse_certificate_supersede(array $user,string $id,string $reason):string
{
 if(!qhse_can_approve($user))throw new DomainException('Your role cannot supersede issued certificates.',403);if(trim($reason)==='')throw new DomainException('Add the reason for this revision.',422);$old=qhse_certificate($user,$id,true);if($old['status']!=='ISSUED')throw new DomainException('Only an issued certificate can be superseded.',409);$pdo=db();$pdo->beginTransaction();try{$newId=uuid();$number=qhse_certificate_number($user);db()->prepare("INSERT INTO qhse_certificates(id,owner_id,certificate_number,revision_number,supersedes_id,template_id,template_version,certificate_type,status,brand_id,customer_id,customer_site,customer_po,customer_reference,project_job,location,test_date,validity_duration,validity_unit,inspection_test_type,procedure_reference,standard_reference,technician_id,inspector_id,reviewer_id,approver_id,client_representative,signoff_date,result,observations,remarks,technical_data,verification_token,created_by) SELECT ?,owner_id,?,revision_number+1,id,template_id,template_version,certificate_type,'DRAFT',brand_id,customer_id,customer_site,customer_po,customer_reference,project_job,location,test_date,validity_duration,validity_unit,inspection_test_type,procedure_reference,standard_reference,technician_id,inspector_id,reviewer_id,approver_id,client_representative,signoff_date,result,observations,remarks,technical_data,?,? FROM qhse_certificates WHERE id=? AND owner_id=?")->execute([$newId,$number,bin2hex(random_bytes(16)),$user['id'],$id,$user['owner_id']]);db()->prepare('INSERT INTO qhse_certificate_equipment(certificate_id,equipment_id,customer_equipment_id,connection_detail,sort_order) SELECT ?,equipment_id,customer_equipment_id,connection_detail,sort_order FROM qhse_certificate_equipment WHERE certificate_id=?')->execute([$newId,$id]);db()->prepare('INSERT INTO qhse_certificate_reference_equipment(certificate_id,equipment_id,reference_role,traceability_note,traceability_data) SELECT ?,equipment_id,reference_role,traceability_note,traceability_data FROM qhse_certificate_reference_equipment WHERE certificate_id=?')->execute([$newId,$id]);db()->prepare('INSERT INTO qhse_certificate_signatories(certificate_id,signatory_role,personnel_user_id,signature_asset_id,signatory_name,role_title,signed_at) SELECT ?,signatory_role,personnel_user_id,signature_asset_id,signatory_name,role_title,signed_at FROM qhse_certificate_signatories WHERE certificate_id=?')->execute([$newId,$id]);db()->prepare("UPDATE qhse_certificates SET status='SUPERSEDED',superseded_by_id=? WHERE id=?")->execute([$newId,$id]);qhse_certificate_event($user,$id,'CERTIFICATE_SUPERSEDED','ISSUED','SUPERSEDED',$reason);qhse_certificate_event($user,$newId,'CERTIFICATE_REVISION_CREATED',null,'DRAFT',$reason);$pdo->commit();return $newId;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
