function qhse_certificate_duplicate(array $user,string $id):string
{
 if(!qhse_can_manage($user))throw new DomainException('Your role cannot duplicate certificates.',403);$source=qhse_certificate($user,$id,true);if($source['certificate_type']!=='HYDROSTATIC_PRESSURE_TEST')throw new DomainException('Duplicate is currently available only for Pressure Test Certificates.',422);
 $pdo=db();$pdo->beginTransaction();try{$newId=uuid();$number=qhse_certificate_number($user);$technical=json_decode((string)$source['technical_data'],true)?:[];foreach(['overall_result','result_statement'] as $key)$technical[$key]='';unset($technical['failure_observations']);
  db()->prepare("INSERT INTO qhse_certificates(id,owner_id,certificate_number,duplicated_from_certificate_id,template_id,template_version,certificate_type,status,brand_id,customer_id,customer_po,customer_reference,nuprc_number,project_job,location,validity_duration,validity_unit,inspection_test_type,certificate_description,procedure_reference,standard_reference,technician_id,inspector_id,client_representative,technical_data,verification_token,created_by) SELECT ?,owner_id,?,id,template_id,template_version,certificate_type,'DRAFT',brand_id,customer_id,customer_po,customer_reference,nuprc_number,project_job,location,validity_duration,validity_unit,inspection_test_type,certificate_description,procedure_reference,standard_reference,technician_id,inspector_id,client_representative,?,?,? FROM qhse_certificates WHERE id=? AND owner_id=?")->execute([$newId,$number,json_encode($technical,JSON_THROW_ON_ERROR),bin2hex(random_bytes(16)),$user['id'],$id,$user['owner_id']]);
  db()->prepare('INSERT INTO qhse_certificate_equipment(certificate_id,equipment_id,customer_equipment_id,connection_detail,sort_order) SELECT ?,equipment_id,customer_equipment_id,connection_detail,sort_order FROM qhse_certificate_equipment WHERE certificate_id=?')->execute([$newId,$id]);db()->prepare('INSERT INTO qhse_certificate_reference_equipment(certificate_id,equipment_id,reference_role,traceability_note,traceability_data) SELECT ?,equipment_id,reference_role,traceability_note,traceability_data FROM qhse_certificate_reference_equipment WHERE certificate_id=?')->execute([$newId,$id]);db()->prepare('INSERT INTO qhse_pressure_test_items(id,certificate_id,equipment_id,assembly_id,item_name,asset_code,range_text,test_pressure,equipment_snapshot,sort_order) SELECT UUID(),?,equipment_id,assembly_id,item_name,asset_code,range_text,test_pressure,equipment_snapshot,sort_order FROM qhse_pressure_test_items WHERE certificate_id=?')->execute([$newId,$id]);qhse_certificate_event($user,$newId,'CERTIFICATE_DUPLICATED',null,'DRAFT','Duplicated from '.$source['certificate_number']);$pdo->commit();return $newId;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function qhse_certificate_snapshot(array $user,array $certificate):array
{
 $brand=null;if($certificate['brand_id']){$brand=rows('SELECT * FROM commercial_brands WHERE id=? AND organization_id=?',[$certificate['brand_id'],$user['owner_id']])[0]??null;if($brand)foreach(['logo','header','footer'] as $asset)$brand[$asset.'_data']=$brand[$asset.'_data']?base64_encode($brand[$asset.'_data']):null;}
 $signatories=$certificate['signatories']??[];unset($certificate['signatories']);foreach($signatories as &$signatory){foreach(['signature_data','stamp_data'] as $field)if(!empty($signatory[$field]))$signatory[$field]=base64_encode($signatory[$field]);}unset($signatory);return ['certificate'=>$certificate,'brand'=>$brand,'signatories'=>$signatories,'template'=>['id'=>$certificate['template_id'],'version'=>$certificate['template_version'],'presentation'=>json_decode($certificate['presentation_schema'],true),'legal_statement'=>$certificate['legal_statement']],'captured_at'=>gmdate('c')];
}
