 db()->prepare('INSERT INTO qhse_completion_alerts(id,owner_id,source_type,source_id,title,missing_fields,created_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),missing_fields=VALUES(missing_fields),status="OPEN",resolved_at=NULL')->execute([uuid(),$user['owner_id'],$type,$id,$title,json_encode(array_values($missing),JSON_THROW_ON_ERROR),$user['id']]);
}
function qhse_signature_file(array $file,string $label):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>3*1024*1024)throw new DomainException($label.' must be a PNG or JPEG up to 3 MB.',422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);if(!in_array($mime,['image/png','image/jpeg'],true))throw new DomainException($label.' must be a PNG or JPEG.',422);return [$mime,file_get_contents((string)$file['tmp_name'])];}
function qhse_signature_save(array $user,array $input,array $files):string
{
 if(!qhse_can_approve($user))throw new DomainException('Your role cannot manage signatures and stamps.',403);$person=qhse_text($input,'personnel_user_id',36);if($person&&!rows('SELECT 1 FROM users WHERE id=? AND owner_id=?',[$person,$user['owner_id']]))throw new DomainException('Choose personnel from your organization.',422);if($person&&rows('SELECT 1 FROM qhse_signature_assets WHERE owner_id=? AND personnel_user_id=?',[$user['owner_id'],$person]))throw new DomainException('This personnel member already has a signature asset.',409);[$signatureMime,$signatureData]=qhse_signature_file($files['signature']??[],'Signature');[$stampMime,$stampData]=qhse_signature_file($files['stamp']??[],'Company stamp');if(!$signatureData&&!$stampData)throw new DomainException('Upload a signature, company stamp, or both.',422);$name=qhse_text($input,'signatory_name',255,true);$id=uuid();db()->prepare('INSERT INTO qhse_signature_assets(id,owner_id,asset_name,personnel_user_id,signatory_name,role_title,signature_mime,signature_data,stamp_mime,stamp_data,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],$name,$person?:null,$name,qhse_text($input,'role_title',255),$signatureMime,$signatureData,$stampMime,$stampData,$user['id']]);operation_audit($user,'qhse.signature_asset_created','qhse_signature_asset',$id,null,['signatory_name'=>$name]);return $id;
}
function qhse_quick_create(array $user,string $kind,array $input):array
{
 if(!qhse_can_manage($user))throw new DomainException('Your role cannot create supporting records.',403);
 if($kind==='equipment'){$name=qhse_text($input,'name',255,true);$aid=qhse_text($input,'asset_code',100,true);$serial=qhse_text($input,'serial_no',100,true);if(rows('SELECT 1 FROM equipment WHERE owner_id=? AND asset_code=?',[$user['owner_id'],$aid]))throw new DomainException('That AID is already in use.',409);$unit=qhse_text($input,'unit_id',36)?:equipment_default_unit($user);if(!rows('SELECT 1 FROM units u JOIN plants p ON p.id=u.plant_id JOIN sites s ON s.id=p.site_id JOIN spaces sp ON sp.id=s.space_id WHERE u.id=? AND sp.owner_id=?',[$unit,$user['owner_id']]))throw new DomainException('Choose an accessible equipment location.',422);$lower=filter_var($input['measurement_lower']??null,FILTER_VALIDATE_FLOAT,FILTER_NULL_ON_FAILURE);$upper=filter_var($input['measurement_upper']??null,FILTER_VALIDATE_FLOAT,FILTER_NULL_ON_FAILURE);if($lower!==null&&$upper!==null&&$lower>$upper)throw new DomainException('The lower range cannot exceed the upper range.',422);$measurementUnit=strtoupper(qhse_text($input,'measurement_unit',30));$allowedUnits=['PSI','BAR','KPA','MPA','PA','KG/CM²','°C','°F','L/MIN','M³/H','V','A','HZ','RPM'];if($measurementUnit!==''&&!in_array($measurementUnit,$allowedUnits,true))throw new DomainException('Choose a valid measurement unit.',422);$brandId=null;$modelId=null;$manufacturer=qhse_text($input,'manufacturer',150);$model=qhse_text($input,'model',150);if($manufacturer!==''){$brandId=rows('SELECT id FROM equipment_brands WHERE name=? AND (owner_id=? OR owner_id IS NULL) ORDER BY owner_id IS NULL LIMIT 1',[$manufacturer,$user['owner_id']])[0]['id']??null;if(!$brandId){$brandId=uuid();db()->prepare('INSERT INTO equipment_brands(id,owner_id,name) VALUES(?,?,?)')->execute([$brandId,$user['owner_id'],$manufacturer]);}if($model!==''){$modelId=rows('SELECT id FROM equipment_models WHERE brand_id=? AND name=? AND (owner_id=? OR owner_id IS NULL) ORDER BY owner_id IS NULL LIMIT 1',[$brandId,$model,$user['owner_id']])[0]['id']??null;if(!$modelId){$modelId=uuid();db()->prepare('INSERT INTO equipment_models(id,owner_id,brand_id,name) VALUES(?,?,?,?)')->execute([$modelId,$user['owner_id'],$brandId,$model]);}}}equipment_seed_statuses($user['owner_id']);$status=rows("SELECT id FROM equipment_statuses WHERE owner_id=? AND operational_state='OPERATIONAL' AND is_default=1 LIMIT 1",[$user['owner_id']])[0]['id']??null;$id=uuid();db()->prepare("INSERT INTO equipment(id,owner_id,unit_id,asset_code,name,serial_no,short_description,brand_id,model_id,measurement_lower,measurement_upper,measurement_unit,measurement_accuracy,calibration_date,calibration_due_date,calibration_certificate_number,calibration_status,status,status_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'OPERATIONAL',?)")->execute([$id,$user['owner_id'],$unit,$aid,$name,$serial,qhse_text($input,'description',500),$brandId,$modelId,$lower,$upper,$measurementUnit?:null,qhse_text($input,'measurement_accuracy',100),qhse_text($input,'calibration_date',10)?:null,qhse_text($input,'calibration_due_date',10)?:null,qhse_text($input,'calibration_certificate_number',150),qhse_text($input,'calibration_status',60),$status]);qhse_completion_alert($user,'EQUIPMENT',$id,'Complete equipment profile: '.$name,['category','subcategory','equipment type','manufacture year','photos','technical specifications']);operation_audit($user,'qhse.quick_equipment_created','equipment',$id,null,['name'=>$name,'aid'=>$aid,'completion_required'=>true]);return ['id'=>$id,'label'=>$name,'meta'=>$aid.' · '.$serial,'traceability'=>['description'=>qhse_text($input,'description',500),'manufacturer'=>$manufacturer,'model'=>$model,'lower'=>$lower,'upper'=>$upper,'unit'=>$measurementUnit,'accuracy'=>qhse_text($input,'measurement_accuracy',100),'calibration_date'=>qhse_text($input,'calibration_date',10),'calibration_due_date'=>qhse_text($input,'calibration_due_date',10),'calibration_certificate_number'=>qhse_text($input,'calibration_certificate_number',150),'calibration_status'=>qhse_text($input,'calibration_status',60)],'message'=>'Equipment added to the canonical register and selected.'];}
 if($kind==='customer'){$id=commercial_customer_save($user,['name'=>qhse_text($input,'name',255,true),'customer_code'=>qhse_text($input,'customer_code',100),'primary_contact'=>qhse_text($input,'primary_contact',255),'billing_address'=>qhse_text($input,'billing_address',5000),'currency'=>'NGN']);qhse_completion_alert($user,'CUSTOMER',$id,'Complete customer profile: '.qhse_text($input,'name',255,true),['email','phone','delivery/service address','tax information']);return ['id'=>$id,'label'=>qhse_text($input,'name',255,true),'meta'=>qhse_text($input,'customer_code',100),'message'=>'Customer added. Complete commercial and tax details later.'];}
 if($kind==='brand'){$name=qhse_text($input,'brand_name',255,true);$company=qhse_text($input,'company_name',255,true);$id=commercial_brand_save($user,['creation_mode'=>'ELEMENTS','brand_name'=>$name,'company_name'=>$company,'addresses'=>[],'phones'=>[],'emails'=>[],'website'=>''],[]);qhse_completion_alert($user,'BRAND',$id,'Complete document brand: '.$name,['logo','address','phone','email','website']);return ['id'=>$id,'label'=>$name,'meta'=>$company,'message'=>'Brand added. Add its logo and contact details later.'];}
 if($kind==='template'){$name=qhse_text($input,'name',255,true);$type=qhse_text($input,'certificate_type',60,true);$base=rows('SELECT * FROM qhse_certificate_templates WHERE certificate_type=? AND owner_id IS NULL LIMIT 1',[$type])[0]??null;if(!$base)throw new DomainException('Choose a supported certificate family.',422);$version=(int)(rows('SELECT COALESCE(MAX(version),0)+1 n FROM qhse_certificate_templates WHERE owner_id=? AND certificate_type=?',[$user['owner_id'],$type])[0]['n']??1);$id=uuid();db()->prepare('INSERT INTO qhse_certificate_templates(id,owner_id,certificate_type,name,version,field_schema,presentation_schema,legal_statement,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],$type,$name,$version,$base['field_schema'],$base['presentation_schema'],$base['legal_statement'],$user['id']]);qhse_completion_alert($user,'CERTIFICATE_TEMPLATE',$id,'Complete certificate template: '.$name,['section layout','legal statement','signature positions','QR presentation']);return ['id'=>$id,'label'=>$name.' · v'.$version,'meta'=>qhse_certificate_type_label($type),'type'=>$type,'message'=>'Template added from the standard family. Customize presentation later.'];}
 if($kind==='personnel'){$name=qhse_text($input,'full_name',255,true);$email=strtolower(qhse_text($input,'email',255,true));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Enter a valid email address.',422);if(rows('SELECT 1 FROM users WHERE email=?',[$email]))throw new DomainException('That email already belongs to a user.',409);$id=uuid();$placeholderPhone='QHSE-'.substr(str_replace('-','',$id),0,20);db()->prepare("INSERT INTO users(id,owner_id,full_name,email,phone,password_hash,is_email_verified,is_active,role) VALUES(?,?,?,?,?,?,0,1,'OPERATOR')")->execute([$id,$user['owner_id'],$name,$email,$placeholderPhone,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT)]);$location=operation_locations($user)[0]??null;if($location)db()->prepare('INSERT INTO user_scopes(id,user_id,site_id,unit_id) VALUES(?,?,?,?)')->execute([uuid(),$id,$location['site_id'],$location['unit_id']]);qhse_completion_alert($user,'OPERATOR',$id,'Complete operator profile: '.$name,['phone','position','competence records','authorization','account activation']);operation_audit($user,'qhse.quick_operator_created','user',$id,null,['name'=>$name,'role'=>'OPERATOR','completion_required'=>true]);return ['id'=>$id,'label'=>$name,'meta'=>'Operator · profile incomplete','message'=>'Operator added. Complete competence, authorization and account activation later.'];}
 throw new DomainException('Unsupported quick-create record.',422);
}
